def _ll(A, y):
    b = np.zeros(A.shape[1])
    for _ in range(40):
        z = A @ b
        q = 1 / (1 + np.exp(-np.clip(z, -30, 30)))
        w = np.maximum(q * (1 - q), 1e-8)
        H = A.T @ (w[:, None] * A) + 1e-6 * np.eye(len(b))
        d = np.linalg.solve(H, A.T @ (y - q))
        d *= min(1., 5. / max(5., np.max(np.abs(d))))
        old = np.sum(y * z - np.logaddexp(0, z))
        for _ in range(15):
            t = A @ (b + d)
            if np.sum(y * t - np.logaddexp(0, t)) >= old - 1e-9: break
            d *= .5
        b += d
        if np.max(np.abs(d)) < 1e-7: break
    z = A @ b
    return float(np.sum(y * z - np.logaddexp(0, z)))

def design(feats) -> Design:
    X, y, ids = np.asarray(feats.x, float), np.asarray(feats.y, float), tuple(feats.ids)
    n, p = X.shape
    if p == 0 or n < 10 or len(np.unique(y)) < 2 or MAX_DRIVERS < 1:
        return Design(drivers=(), columns=(), products=(), loadings={})
    Z = X - X.mean(axis=0)
    Z /= np.maximum(np.sqrt(np.sum(Z * Z, axis=0)), 1e-12)
    R = Z.T @ Z
    labs = list(dict.fromkeys(feats.stratum))
    S = np.column_stack([np.ones(n)] + [np.array(feats.stratum) == l for l in labs[1:]])
    degree = (np.abs(R) >= .6).sum(axis=0) - 1
    hubs = []
    for j in np.argsort(-degree, kind='stable'):
        if feats.types[j] == 'clinical' and degree[j] >= 3:
            if not any(abs(R[j, k]) >= .8 for k in hubs): hubs.append(int(j))
        if len(hubs) == 3: break
    cache = {}
    def ll(cols, extra=None):
        key = tuple(sorted(set(cols)))
        A = np.column_stack((S, X[:, key]))
        if extra is not None:
            v = extra - extra.mean()
            return _ll(np.column_stack((A, v / max(v.std(), 1e-8))), y)
        if key not in cache: cache[key] = _ll(A, y)
        return cache[key]
    sel, alpha = [], .05 / p
    for _ in range(min(MAX_DRIVERS, p)):
        best, bj = 1., None
        for j in range(p):
            if j in sel or any(abs(R[j, k]) >= .85 for k in sel): continue
            adj = sorted((set(sel) | set(hubs)) - {j})
            pv = stats.chi2.sf(max(0., 2 * (ll(adj + [j]) - ll(adj))), 1)
            if pv < best: best, bj = pv, j
        if bj is None or best > alpha: break
        sel.append(bj)
    for j in list(reversed(sel)):
        adj = sorted((set(sel) | set(hubs)) - {j})
        if stats.chi2.sf(max(0., 2 * (ll(adj + [j]) - ll(adj))), 1) > alpha: sel.remove(j)
    best, pair = 1., None
    for a in range(p):
        for b in range(a, p):
            if a != b and abs(R[a, b]) >= .85: continue
            if len(set(sel) | {a, b}) > MAX_DRIVERS: continue
            cols = sorted(set(sel) | set(hubs) | {a, b})
            pv = stats.chi2.sf(max(0., 2 * (ll(cols, X[:, a] * X[:, b]) - ll(cols))), 1)
            if pv < best: best, pair = pv, (a, b)
    products = []
    if pair is not None and best < .01 / (p * (p + 1) / 2):
        products = [(ids[pair[0]], ids[pair[1]])]
        sel = list(dict.fromkeys(sel + list(pair)))
    cols = sorted(set(sel) | set(hubs)) if sel else []
    return Design(drivers=tuple(ids[j] for j in sel), columns=tuple(ids[j] for j in cols),
                  products=tuple(products), loadings={})

